select.if:
select
SUM(AMOUNT)
from PTL_CASH_POSITION_FLOW
where CDATE <= #{cdate,jdbcType=DATE}


    and ACCT_ID in (
    SELECT ACCT_NO from PTL_CAPACCT_INFO where PORTFOLIO_ID = #{portfolioId}
    #{item}
    )

and (is_exist_new is null or  is_exist_new!='Y')

SELECT SUM(pcpf.AMOUNT)
FROM PTL_CASH_POSITION_FLOW pcpf
left join FIN_PRODUCT fp on fp.FINPROD_ID = pcpf.CHL_FINPROD_ID
WHERE pcpf.CDATE <= #{cdate,jdbcType=DATE}

    and pcpf.HODING_TYPE = #{hodingType,jdbcType=VARCHAR}


    AND ( fp.FINPROD_MARKET_ID = #{chlFinprodId,jdbcType=VARCHAR} or pcpf.CHL_FINPROD_ID = #{chlFinprodId,jdbcType=VARCHAR} )


    and pcpf.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}


    and pcpf.CCY = #{ccy,jdbcType=VARCHAR}


    and pcpf.ACCT_ID in (
    SELECT sfpa.ACCT_NO from STL_FIN_PRODUCT_ACCT sfpa where sfpa.FINPROD_ID = fp.FINPROD_ID
    #{item}
    )

and (is_exist_new is null or  is_exist_new!='Y')

