mapper.update:
update PTL_CASH_POSITION


        AMOUNT = AMOUNT + #{amount,jdbcType=DECIMAL},


        CHL_FINPROD_ID = #{chlFinprodId,jdbcType=VARCHAR},


        UPDATE_USER = #{updateUser,jdbcType=VARCHAR},


        UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP},


where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and ACCT_ID = #{acctId,jdbcType=VARCHAR}
and HODING_TYPE = #{hodingType,jdbcType=VARCHAR}
and CDATE = #{cdate,jdbcType=DATE}
and CCY = #{ccy,jdbcType=VARCHAR}

mapper.select:
select
sum(a.AMOUNT*nvl(b.CAL_FLAG,1)) AS amount
from PTL_CASH_POSITION_RULE a
LEFT JOIN PTL_POSITION_CFG b
ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE  = #{hodingType,jdbcType=VARCHAR}
where a.cdate =#{cdate,jdbcType=DATE}
and b.S_HOLDINGTYPE =#{hodingType,jdbcType=VARCHAR}
and a.ccy = #{ccy,jdbcType=VARCHAR}
AND a.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and a.DATE_TYPE=#{dateType,jdbcType=INTEGER}
